const STAGE_FALLBACK: InsectStage[] = ['adult', 'larva', 'nymph', 'pupa', 'egg', 'damage'];

/** Return a public URL for an image of the given insect, preferring the requested stage. */
export function getInsectImage(id: string, stage: InsectStage = 'adult'): string | null {
  const entry = INSECT_IMAGES[id];
  if (!entry) return null;
  const preferred = entry[stage];
  const order = [stage, ...STAGE_FALLBACK.filter((s) => s !== stage)];
  for (const s of order) {
    const file = entry[s];
    if (file) return `/assets/images/${entry.folder}/${file}`;
  }
  return preferred ? `/assets/images/${entry.folder}/${preferred}` : null;
}

export function hasInsectImage(id: string): boolean {
  return !!INSECT_IMAGES[id];
}
